    @Tag("C3B_GATE_B") @Test void noCommittedOrTransientIdleSlot()throws Exception {
        var q=qualify();jdbc.execute("CREATE FUNCTION ddip_management.no_idle() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.active_attempt_id IS NOT NULL AND NEW.active_attempt_id IS NULL THEN RAISE EXCEPTION USING MESSAGE='PRIVATE',ERRCODE='23514'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER no_idle BEFORE UPDATE ON ddip_management.coordinator FOR EACH ROW EXECUTE FUNCTION ddip_management.no_idle()");
        var inside=new CountDownLatch(1);var release=new CountDownLatch(1);var repo=repository(step->{if(step==RecoveryHandoff.Step.COORDINATOR){inside.countDown();try{assertThat(release.await(2,TimeUnit.SECONDS)).isTrue();}catch(InterruptedException ex){throw new RuntimeException(ex);}}});
        try(var pool=Executors.newSingleThreadExecutor()){var task=pool.submit(()->repo.transfer(guard,q));assertThat(inside.await(10,TimeUnit.SECONDS)).isTrue();assertThat(jdbc.queryForObject("SELECT active_attempt_id FROM ddip_management.coordinator",UUID.class)).isEqualTo(owner.attemptId());release.countDown();assertThat(task.get(10,TimeUnit.SECONDS).owner()).isNotNull();}finally{release.countDown();}
        assertThat(jdbc.queryForObject("SELECT active_attempt_id FROM ddip_management.coordinator",UUID.class)).isEqualTo(control);assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.attempts WHERE state IN ('CLAIMED','RUNNING')",Long.class)).isEqualTo(1);
    }
