    @ParameterizedTest @ValueSource(strings={"empty","stages","terminal","parquet"}) void retainedPacketReconstructsExactCommitWithoutEffects(String kind)throws Exception {
        if(kind.equals("parquet")){guard.close();guard=null;jdbc.execute("DROP SCHEMA ddip_management CASCADE");new SchemaLifecycle(Flyway.configure().dataSource(jdbc.getDataSource()).defaultSchema("ddip_management").schemas("ddip_management").load(),jdbc,new JdbcCoordinatorRepository(jdbc,tx,INSTALL)).verify(true);provision("PARQUET");}
        if(kind.equals("stages")){stage("CHECK_INPUTS","INTENT");stage("PUBLISH_RELIABILITY","RUNNING");stage("VERIFY_RESULT","VERIFIED");}
        if(kind.equals("terminal"))rebuild("RECONCILE","RECOVERY_REQUIRED","FAILED");
        var q=qualify();var expected=handoffs.transfer(guard,q).owner();var sql=snapshot();var nativeFiles=nativeSnapshot();var privateFiles=privateSnapshot();
        // A fresh repository has no Qualified handle or transfer result. Only exact retained bytes are supplied.
        handoffs=repository(step->{throw new AssertionError("Bootstrap attempted mutation");});
        for(int i=0;i<3;i++){var b=bootstrap();assertThat(b.toString()).isEqualTo("RecoveryBootstrap[redacted]");assertThat(handoffs.resolve(b).status()).isEqualTo(RecoveryHandoff.Status.CONFIRMED_HANDOFF);assertThat(handoffs.authorize(guard,b,freshReview(b))).isEqualTo(expected);}
        assertThat(snapshot()).isEqualTo(sql);assertThat(nativeSnapshot()).isEqualTo(nativeFiles);assertThat(privateSnapshot()).isEqualTo(privateFiles);assertThat(count("attempts")).isEqualTo(2);assertThat(count("stage_artifacts")).isZero();
        assertThatThrownBy(()->WorkerTestSupport.reliability(jdbc,tx,INSTALL).claim(guard,expected.worker(),UUID.randomUUID())).hasMessage("WORKER_NOT_READY");assertThat(snapshot()).isEqualTo(sql);
    }
    Map<String,String> privateSnapshot()throws Exception {var result=new TreeMap<String,String>();try(var paths=Files.walk(binding.root())){for(Path p:paths.sorted().toList()){var a=Files.readAttributes(p,java.nio.file.attribute.BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);result.put(binding.root().relativize(p).toString(),a.lastModifiedTime()+":"+a.size()+":"+(a.isRegularFile()?SourceJson.sha(Files.readAllBytes(p)):"directory"));}}return result;}
