    @ParameterizedTest @ValueSource(strings={"missing","truncated","altered","symlink","parentSymlink","hardlink","public","oversize"}) void unsafeRetainedPacketFailsClosed(String mode)throws Exception {
        var q=qualify();handoffs.transfer(guard,q);Path packet=binding.root().resolve(q.address());
        switch(mode){case "missing"->Files.delete(packet);case "truncated"->Files.write(packet,new byte[0]);case "altered"->Files.writeString(packet," ",StandardOpenOption.APPEND);case "symlink"->{Files.delete(packet);Files.createSymbolicLink(packet,work.resolve("source-catalog.json"));}case "hardlink"->Files.createLink(packet.resolveSibling("other.json"),packet);case "public"->Files.setPosixFilePermissions(packet,java.nio.file.attribute.PosixFilePermissions.fromString("rw-r--r--"));case "oversize"->Files.write(packet,new byte[RecoveryFiles.MAXIMUM+1]);case "parentSymlink"->{Path parent=packet.getParent(),moved=parent.resolveSibling("moved");Files.move(parent,moved);Files.createSymbolicLink(parent,moved);}}
        var before=snapshot();assertThatThrownBy(this::bootstrap).isInstanceOf(RecoveryFailure.class).hasNoCause().hasMessageMatching("EVIDENCE_(CHANGED|UNAVAILABLE)");assertThat(snapshot()).isEqualTo(before);
    }
    @ParameterizedTest @ValueSource(strings={"unknown","version","versionOverflow","installation","control","profile","snapshot","review","runtime","metadataType","metadataField","byteProjection","noncanonical","duplicate","address"}) void malformedOrContradictoryPacketIsRejectedWithBoundedDiagnostics(String mode)throws Exception {
        var q=qualify();handoffs.transfer(guard,q);Path path=binding.root().resolve(q.address());var n=(ObjectNode)SourceJson.parse(Files.readAllBytes(path),RecoveryFiles.MAXIMUM);
        switch(mode){case "unknown"->n.put("private-secret","/private/secret");case "version"->n.put("qualificationVersion",2);case "versionOverflow"->n.put("qualificationVersion",4294967297L);case "installation"->n.put("installationId",UUID.randomUUID().toString());case "control"->n.put("controlId",UUID.randomUUID().toString());case "profile"->n.put("runProfileSha256","b".repeat(64));case "snapshot"->n.put("snapshotSha256","b".repeat(64));case "review"->((ObjectNode)n.get("operatorReview")).put("handlersStopped",false);case "runtime"->n.put("runtimeSha256","b".repeat(64));case "metadataType"->((ObjectNode)n.get("originalMetadata").get(0)).put("row_version",1);case "metadataField"->((ObjectNode)n.get("originalMetadata").get(0)).put("unknown","secret");case "byteProjection"->((ObjectNode)n.get("originalMetadata").get(1).get("captured_selection")).put("length","-1");}
        if(Set.of("metadataType","metadataField","byteProjection").contains(mode))n.put("snapshotSha256",SourceJson.sha(SourceJson.canonical(n.get("originalMetadata"))));
        byte[] raw=SourceJson.canonical(n);if(mode.equals("noncanonical"))raw=(new String(raw,java.nio.charset.StandardCharsets.UTF_8)+" ").getBytes(java.nio.charset.StandardCharsets.UTF_8);if(mode.equals("duplicate"))raw="{\"qualificationVersion\":1,\"qualificationVersion\":1}".getBytes(java.nio.charset.StandardCharsets.UTF_8);Files.write(path,raw);String sha=SourceJson.sha(raw);String address=mode.equals("address")?"recovery/../"+q.address():q.address();var before=snapshot();
        assertThatThrownBy(()->handoffs.bootstrap(guard,address,sha,RUNTIME)).isInstanceOf(RecoveryFailure.class).hasNoCause().hasMessageMatching("[A-Z_]{1,40}");assertThat(snapshot()).isEqualTo(before);
    }
    @ParameterizedTest @ValueSource(strings={"missing","changed","replacement","symlink","appeared"}) void bootstrapRechecksAllPrivateSidecarEvidence(String mode)throws Exception {
        UUID cp=stage("CHECK_INPUTS","INTENT");var q=qualify();handoffs.transfer(guard,q);Path command=new PreflightFiles(guard,run,owner.attemptId(),cp).directory.resolve("command.json");byte[] raw=Files.readAllBytes(command);
        if(mode.equals("changed"))Files.writeString(command," ",StandardOpenOption.APPEND);else if(mode.equals("appeared")){Path added=command.resolveSibling("result.json");Files.writeString(added,"{}");Files.setPosixFilePermissions(added,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));}else{Files.move(command,command.resolveSibling("retired.json"));if(mode.equals("replacement")){Files.write(command,raw);Files.setPosixFilePermissions(command,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));}if(mode.equals("symlink"))Files.createSymbolicLink(command,command.resolveSibling("retired.json"));}
        var before=snapshot();assertThatThrownBy(this::bootstrap).isInstanceOf(RecoveryFailure.class).hasNoCause();assertThat(snapshot()).isEqualTo(before);
    }
    @ParameterizedTest @ValueSource(strings={"packet","sidecar","runtime","guard","version"}) void authorizationRechecksEvidenceAfterBootstrap(String change)throws Exception {
        UUID cp=stage("CHECK_INPUTS","INTENT");var q=qualify();var token=handoffs.transfer(guard,q).owner();var b=bootstrap();
        switch(change){case "packet"->{Path path=binding.root().resolve(q.address());byte[] raw=Files.readAllBytes(path);var modified=Files.getLastModifiedTime(path);Files.move(path,path.resolveSibling("retired.json"));Files.write(path,raw);Files.setPosixFilePermissions(path,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));Files.setLastModifiedTime(path,modified);}case "sidecar"->Files.writeString(new PreflightFiles(guard,run,owner.attemptId(),cp).directory.resolve("command.json")," ",StandardOpenOption.APPEND);case "runtime"->Files.writeString(work.resolve("deployment/service_reference.py"),"# changed",StandardOpenOption.APPEND);case "guard"->guard.close();case "version"->handoffs.heartbeat(guard,token);}
        var before=snapshot();assertThatThrownBy(()->handoffs.authorize(guard,b,freshReview(b))).isInstanceOf(RecoveryFailure.class).hasNoCause();assertThat(snapshot()).isEqualTo(before);
    }
    @Test void historicalReceiptNeverRefreshesAfterHeartbeat(){var q=qualify();var token=handoffs.transfer(guard,q).owner();var b=bootstrap();handoffs.heartbeat(guard,token);var before=snapshot();assertThat(handoffs.resolve(b).status()).isEqualTo(RecoveryHandoff.Status.UNRESOLVED);assertThatThrownBy(this::bootstrap).hasMessage("HANDOFF_UNRESOLVED");assertThat(snapshot()).isEqualTo(before);}
    @Test void expiredHistoricalReviewRequiresExplicitFreshReview(){var q=qualify();handoffs.transfer(guard,q);var oldReview=review(target);clock.now=clock.now.plusSeconds(61);var b=bootstrap();var before=snapshot();assertThatThrownBy(()->handoffs.authorize(guard,b,oldReview)).hasMessage("FRESH_QUALIFICATION_REQUIRED");assertThat(handoffs.authorize(guard,b,freshReview(b))).isNotNull();assertThat(snapshot()).isEqualTo(before);}
    @ParameterizedTest @ValueSource(strings={"LIVE","UNAVAILABLE","ABSENT","REUSED","exception"}) void uncertainRecoveryIdentityCannotAuthorize(String state){var q=qualify();handoffs.transfer(guard,q);var b=bootstrap();var repo=new RecoveryHandoff(jdbc,tx,INSTALL,clock,p->{if(p.pid()==guard.process().pid()){if(state.equals("exception"))throw new IllegalStateException("PRIVATE");return RecoveryQuiescence.State.valueOf(state);}return RecoveryQuiescence.LOCAL.inspect(p);},step->{});var before=snapshot();if(state.equals("LIVE"))assertThat(repo.authorize(guard,b,freshReview(b))).isNotNull();else assertThatThrownBy(()->repo.authorize(guard,b,freshReview(b))).hasMessage("PROCESS_UNRESOLVED").hasNoCause();assertThat(snapshot()).isEqualTo(before);}
    @Test void oldWriterUncertaintyStillVetoesCurrentAuthorization(){var q=qualify();handoffs.transfer(guard,q);var b=bootstrap();var repo=new RecoveryHandoff(jdbc,tx,INSTALL,clock,p->p.pid()==exitedPid?RecoveryQuiescence.State.UNAVAILABLE:RecoveryQuiescence.LOCAL.inspect(p),step->{});assertThatThrownBy(()->repo.authorize(guard,b,freshReview(b))).hasMessage("PROCESS_UNRESOLVED");}
    @Test void newGuardInstanceCanReadFactsButCannotAdoptHistoricalOwner(){var q=qualify();handoffs.transfer(guard,q);guard.close();guard=InstallationHostGuard.acquire(binding);var before=snapshot();var b=bootstrap();assertThat(handoffs.resolve(b).status()).isEqualTo(RecoveryHandoff.Status.CONFIRMED_HANDOFF);assertThatThrownBy(()->handoffs.authorize(guard,b,freshReview(b))).hasMessage("OWNERSHIP_LOST");assertThat(snapshot()).isEqualTo(before);}
    @Test void outageAndAmbientTransactionsNeverAuthorize(){var q=qualify();handoffs.transfer(guard,q);var b=bootstrap();try{outage(true);assertThat(handoffs.resolve(b).status()).isEqualTo(RecoveryHandoff.Status.UNRESOLVED);assertThatThrownBy(this::bootstrap).hasMessage("HANDOFF_UNRESOLVED");assertThatThrownBy(()->handoffs.authorize(guard,b,freshReview(b))).hasMessage("HANDOFF_UNRESOLVED");}finally{outage(false);}assertThatThrownBy(()->tx.required(this::bootstrap)).hasMessage("INVALID_REQUEST");assertThatThrownBy(()->tx.required(()->handoffs.resolve(b))).hasMessage("INVALID_REQUEST");assertThatThrownBy(()->tx.required(()->handoffs.authorize(guard,b,freshReview(b)))).hasMessage("INVALID_REQUEST");}
    @Test void packetBootstrapSurvivesActualPostgresRestart()throws Exception {
        var q=qualify();handoffs.transfer(guard,q);var before=snapshot();var started=jdbc.queryForObject("SELECT pg_postmaster_start_time()",OffsetDateTime.class);String signal=System.getProperty("ddip.test.bootstrap-restart-signal");
        if(signal!=null){Files.writeString(Path.of(signal),"READY");long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(45);while(!Files.exists(Path.of(signal+".done")) && System.nanoTime()<end)java.util.concurrent.locks.LockSupport.parkNanos(10000000);assertThat(Files.exists(Path.of(signal+".done"))).isTrue();assertThat(jdbc.queryForObject("SELECT pg_postmaster_start_time()",OffsetDateTime.class)).isAfter(started);}
        handoffs=repository(step->{});var b=bootstrap();assertThat(handoffs.resolve(b).status()).isEqualTo(RecoveryHandoff.Status.CONFIRMED_HANDOFF);assertThat(handoffs.authorize(guard,b,freshReview(b)).worker().epoch()).isEqualTo(2);assertThat(snapshot()).isEqualTo(before);
    }
    @Test void bootstrapDoesNotInvokeNativeChild()throws Exception {
        Path invoked=work.resolve("forbidden-child"),executable=work.resolve("forbidden-python");Files.writeString(executable,"#!/bin/sh\ntouch '"+invoked.toString().replace("'","'\\''")+"'\nexit 97\n");Files.setPosixFilePermissions(executable,java.nio.file.attribute.PosixFilePermissions.fromString("rwx------"));
        var config=(ObjectNode)fixture.get("command").get("runtime").get("configuration").deepCopy();config.put("python",executable.toString());insertProfile("no-native-launch",config);
        jdbc.update("INSERT INTO ddip_management.execution_profile_storage SELECT 'no-native-launch',binding_id FROM ddip_management.execution_profile_storage WHERE profile_id=?",RUNTIME);
        var t=inspect();qualification=handoffs.qualify(guard,t,review(t),"no-native-launch");handoffs.transfer(guard,qualification);var before=snapshot();
        var b=handoffs.bootstrap(guard,qualification.address(),qualification.sha256(),"no-native-launch");assertThat(handoffs.authorize(guard,b,freshReview(b))).isNotNull();assertThat(Files.exists(invoked)).isFalse();assertThat(snapshot()).isEqualTo(before);
    }
    @Test void deadRecoveryJvmRequiresNewExplicitControlAndGuardedHandoff()throws Exception {
        admit();guard.close();guard=null;String cp=System.getProperty("surefire.test.class.path",System.getProperty("java.class.path"));
        var child=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin/java").toString(),"-cp",cp,"platform.contentapi.execution.RecoveryBootstrapTestProcess",work.resolve("host.json").toString(),url,user,password,control.toString()).redirectError(ProcessBuilder.Redirect.DISCARD).start();
        String[] retained;
        try{String line;do{line=child.inputReader().readLine();assertThat(line).isNotNull();}while(!line.startsWith("BOOTSTRAP "));retained=line.split(" ");assertThat(child.waitFor(10,TimeUnit.SECONDS)).isTrue();assertThat(child.exitValue()).isZero();}finally{child.destroyForcibly();}
        guard=InstallationHostGuard.acquire(binding);clock.now=Instant.now();var before=snapshot();var historical=handoffs.bootstrap(guard,retained[1],retained[2],RUNTIME);assertThat(handoffs.resolve(historical).status()).isEqualTo(RecoveryHandoff.Status.CONFIRMED_HANDOFF);assertThatThrownBy(()->handoffs.authorize(guard,historical,freshReview(historical))).hasMessage("OWNERSHIP_LOST");assertThat(snapshot()).isEqualTo(before);
        var body=SourceJson.object().put("action","RECONCILE").put("attemptId",control.toString()).put("quiescenceConfirmed",true);UUID nextControl=UUID.fromString(new ControlRepository(jdbc,tx,INSTALL).request(ControlCommands.parse(run.toString(),SourceJson.canonical(body),"after-dead-recovery","\"2\"")).get("controlId").stringValue());
        var nextWorker=new WorkerRepository(jdbc,tx,INSTALL).register(guard,PROFILE,owner.worker().profileDigest(),owner.worker().deploymentDigest());var t=handoffs.inspect(guard,nextWorker,nextControl);var q=handoffs.qualify(guard,t,review(t),RUNTIME);var next=handoffs.transfer(guard,q).owner();assertThat(next.worker().epoch()).isEqualTo(3);assertThat(next.controlId()).isEqualTo(nextControl);assertThat(count("attempts")).isEqualTo(3);
        assertThat(handoffs.resolve(historical).status()).isEqualTo(RecoveryHandoff.Status.UNRESOLVED);assertThatThrownBy(()->handoffs.bootstrap(guard,retained[1],retained[2],RUNTIME)).hasMessage("HANDOFF_UNRESOLVED");assertThat(jdbc.queryForObject("SELECT active_attempt_id FROM ddip_management.coordinator",UUID.class)).isEqualTo(nextControl);
    }
    @Test void wrongHashOrRuntimeAndLostInstallationGuardFailClosed(){var q=qualify();handoffs.transfer(guard,q);var before=snapshot();assertThatThrownBy(()->handoffs.bootstrap(guard,q.address(),"b".repeat(64),RUNTIME)).hasMessage("EVIDENCE_CHANGED");assertThatThrownBy(()->handoffs.bootstrap(guard,q.address(),q.sha256(),"unknown-runtime")).hasMessage("RUNTIME_MISMATCH");guard.close();assertThatThrownBy(this::bootstrap).hasMessage("OWNERSHIP_LOST");assertThat(snapshot()).isEqualTo(before);}
    @Test void guardLostDuringFinalSqlComparisonCannotGrantAuthority(){
        var q=qualify();handoffs.transfer(guard,q);var b=bootstrap();var before=snapshot();var once=new AtomicBoolean(true);
        var closing=new JdbcTemplate(jdbc.getDataSource()){@Override public List<Map<String,Object>> queryForList(String sql){var rows=super.queryForList(sql);if(sql.contains("FROM ddip_management.coordinator") && once.compareAndSet(true,false))guard.close();return rows;}};
        var repo=new RecoveryHandoff(closing,transactions(closing),INSTALL,clock,RecoveryQuiescence.LOCAL,step->{});
        assertThatThrownBy(()->repo.authorize(guard,b,freshReview(b))).hasMessage("OWNERSHIP_LOST");assertThat(once.get()).isFalse();assertThat(snapshot()).isEqualTo(before);
    }
